<?php require_once __DIR__.'/includes/auth.php'; require_login(['admin']);$type=$_GET['type']??'pending';header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="ift-'.$type.'-report-'.date('Y-m-d').'.csv"');$out=fopen('php://output','w');if($type==='released'){$rows=db()->query("SELECT r.tracking_no,c.course_code,c.course_title,c.level,c.semester,r.session_name,GROUP_CONCAT(l.full_name ORDER BY l.id SEPARATOR ', ') lecturer,s.stage_name,r.current_since FROM result_records r JOIN courses c ON c.id=r.course_id JOIN course_lecturers cl ON cl.course_id=c.id JOIN lecturers l ON l.id=cl.lecturer_id JOIN status_stages s ON s.id=r.current_stage_id WHERE s.stage_name='Released to Students' GROUP BY r.id ORDER BY r.current_since DESC")->fetchAll();fputcsv($out,['Tracking No','Course Code','Course Title','Level','Semester','Session','Lecturer','Status','Released Date']);}else{$rows=db()->query("SELECT r.tracking_no,c.course_code,c.course_title,c.level,c.semester,r.session_name,GROUP_CONCAT(l.full_name ORDER BY l.id SEPARATOR ', ') lecturer,s.stage_name,o.office_name,TIMESTAMPDIFF(DAY,r.current_since,NOW()) days FROM result_records r JOIN courses c ON c.id=r.course_id JOIN course_lecturers cl ON cl.course_id=c.id JOIN lecturers l ON l.id=cl.lecturer_id JOIN status_stages s ON s.id=r.current_stage_id LEFT JOIN offices o ON o.id=r.current_office_id WHERE s.stage_order<7 GROUP BY r.id ORDER BY days DESC")->fetchAll();fputcsv($out,['Tracking No','Course Code','Course Title','Level','Semester','Session','Lecturer','Current Stage','Office','Days Pending']);}foreach($rows as $row)fputcsv($out,$row);fclose($out);exit;
